function InfiniteDataGrid({
  caption = "{{caption}}",
  accent = "{{accent}}",
  loading = {{loading}},
  loadedPercent = {{loadedPercent}},
  rowHeight = {{rowHeight}},
}) {
  const rows = [
    ["#1042", "A. Whitfield", "Shipped", "£64.00"],
    ["#1041", "R. Okafor", "Processing", "£128.50"],
    ["#1040", "M. Iqbal", "Shipped", "£22.00"],
    ["#1039", "S. Novak", "Refunded", "£40.00"],
  ];
  const cell = { padding: "0 14px", borderBottom: "1px solid #24143020", whiteSpace: "nowrap" };
  return (
    <div style={{ maxWidth: 480, borderRadius: 10, border: "1px solid #24143020", overflow: "hidden", font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <div style={{ maxHeight: 220, overflowY: "auto" }}>
        <table style={{ borderCollapse: "collapse", width: "100%" }}>
          <caption style={{ textAlign: "left", fontWeight: 600, padding: "10px 14px" }}>{caption}</caption>
          <thead>
            <tr style={{ background: accent, color: "#FAF7F2" }}>
              {["Order", "Customer", "Status", "Total"].map((h) => <th key={h} scope="col" style={{ padding: "10px 14px", textAlign: "left" }}>{h}</th>)}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row[0]} style={{ height: rowHeight }}>{row.map((c, j) => <td key={j} style={cell}>{c}</td>)}</tr>
            ))}
            {loading && (
              <tr aria-hidden="true" style={{ height: rowHeight }}>
                <td colSpan={4} style={{ padding: "0 14px" }}>
                  <span style={{ display: "block", height: 12, borderRadius: 4, background: "#24143020" }} />
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", borderTop: "1px solid #24143020" }}>
        <div style={{ flex: 1, height: 6, borderRadius: 999, background: "#24143014", overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${loadedPercent}%`, background: accent, borderRadius: "inherit" }} />
        </div>
        <span role="status" style={{ fontSize: 12, whiteSpace: "nowrap" }}>{loading ? "Loading more… " : ""}{loadedPercent}% rendered</span>
      </div>
    </div>
  );
}
